{"content":"import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/search_view.dart';
import 'widgets/currency_card.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with WidgetsBindingObserver, TickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<void> _initialLoadFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;
  bool _hasLoadedOnce = false;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    WidgetsBinding.instance.addObserver(this);
    _loadInitial();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitial() async {
    final currencyRepository = context.read<CurrencyRepository>();
    setState(() {
      _currentPage = 0;
      _hasMore = true;
      _isLoadingMore = false;
      _allCurrencies = [];
      _filteredCurrenciesNotifier.value = const [];
    });

    _initialLoadFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20)).then((CurrencyPage page) {
      setState(() {
        _allCurrencies = List.from(page.items);
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
        _currentPage = page.page;
        _hasMore = page.hasMore;

        _fadeController.forward();
      });

      currencyRepository.saveCurrencyList(_allCurrencies);
      setState(() => _hasLoadedOnce = true);
    }).catchError((dynamic error) {
      // ignore — FutureBuilder отобразит пустой виджет
    });
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted && _hasLoadedOnce) {
      _loadInitial();
    }
  }

  Future<void> _loadMore() async {
    if (!_hasMore || _isLoadingMore || !mounted) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();
    final nextPage = _currentPage + 1;

    try {
      final CurrencyPage page = await currencyRepository.fetchRates(
        CurrencyPageRequest(base: 'USD', page: nextPage, pageSize: 20),
      );

      if (mounted) {
        setState(() {
          _allCurrencies.addAll(page.items);
          _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
          _currentPage = page.page;
          _hasMore = page.hasMore;
          _isLoadingMore = false;
        });
      }
    } catch (_) {
      if (mounted) setState(() => _isLoadingMore = false);
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<void>(
        future: _initialLoadFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (!snapshot.hasData && !_hasLoadedOnce) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      final bool showLoadMore = _hasMore && !_isLoadingMore;
                      return ListView.builder(
                        itemCount: data.length + (showLoadMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (index == data.length) {
                            return _buildLoadMoreIndicator(context);
                          }

                          final CurrencyModel currency = data[index];
                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: showLoadMore ? const EdgeInsets.fromLTRB(22, 0, 22, 16) : const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  Widget _buildLoadMoreIndicator(BuildContext context) {
    if (_isLoadingMore) {
      return const Padding(
        padding: EdgeInsets.symmetric(vertical: 16),
        child: Center(child: CircularProgressIndicator()),
      );
    }
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 16),
      child: TextButton(
        onPressed: _loadMore,
        child: Text(context.loc.showMore),
      ),
    );
  }
}
